package com.shopsphere;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;
@Service public class ProductService{private final ProductRepository repo;public ProductService(ProductRepository r){repo=r;}public Product create(ProductDtos.Request r){validate(r,null);Instant n=Instant.now();return repo.save(map(UUID.randomUUID(),r,n,n));}public Product update(UUID id,ProductDtos.Request r){Product old=get(id);validate(r,id);return repo.save(map(id,r,old.createdAt(),Instant.now()));}public Product get(UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Product not found"));}public Product slug(String s){return repo.findBySlug(s).orElseThrow(()->new NotFoundException("Product not found"));}public List<Product>related(UUID id,int limit){return repo.findRelated(get(id),Math.max(1,Math.min(limit,12)));}public Product updateRating(UUID id,double rating,long reviewCount){Product p=get(id);double rounded=Math.round(rating*10.0)/10.0;return repo.save(new Product(p.id(),p.sku(),p.name(),p.slug(),p.description(),p.brand(),p.category(),p.price(),p.originalPrice(),p.discountPercentage(),rounded,reviewCount,p.imageUrls(),p.specifications(),p.active(),p.createdAt(),Instant.now()));}public void delete(UUID id){get(id);repo.delete(id);}public ProductDtos.Page<Product>search(String q,String c,String b,java.math.BigDecimal min,java.math.BigDecimal max,Double rating,String sort,int page,int size){var r=repo.search(q,c,b,min,max,rating,sort,page,size);return new ProductDtos.Page<>(r.content(),page,size,r.total(),(int)Math.ceil(r.total()/(double)size));}public ProductDtos.Page<Product> admin(int page,int size){int p=Math.max(0,page),n=Math.max(1,Math.min(100,size));var all=repo.findAll().stream().sorted(Comparator.comparing(Product::createdAt).reversed()).toList();int start=(int)Math.min((long)p*n,all.size());return new ProductDtos.Page<>(all.subList(start,Math.min(start+n,all.size())),p,n,all.size(),(int)Math.ceil(all.size()/(double)n));}private void validate(ProductDtos.Request r,UUID id){repo.findBySku(r.sku()).filter(p->!p.id().equals(id)).or(()->repo.findBySlug(r.slug()).filter(p->!p.id().equals(id))).ifPresent(p->{throw new ConflictException("SKU or slug already exists");});}private Product map(UUID id,ProductDtos.Request r,Instant c,Instant u){return new Product(id,r.sku(),r.name(),r.slug(),r.description(),r.brand(),r.category(),r.price(),r.originalPrice(),r.discountPercentage(),r.rating(),r.reviewCount(),List.copyOf(r.imageUrls()),r.specifications()==null?Map.of():Map.copyOf(r.specifications()),r.active(),c,u);}}
